/** Normalize a term to a definition key: lowercase, collapse whitespace, strip a
 *  leading article, and map a few common aliases onto the canonical key. */
function definitionKey(term: string): string | null {
  const t = term.toLowerCase().replace(/\s+/g, ' ').replace(/^(the|a|an) /, '').trim();
  const alias: Record<string, string> = {
    passport: 'polity passport',
    'polity-passport': 'polity passport',
    'agent passport': 'polity passport',
    delegate: 'delegation',
    'bounded delegation': 'delegation',
    steward: 'citizenship',
    citizen: 'citizenship',
    person: 'personhood',
    // Anchor-primitive aliases
    'meta me': 'metame',
    'metame runtime': 'metame',
    'metame threshold': 'threshold',
    crossing: 'threshold',
    'metame primitive': 'metame',
  };
  const key = alias[t] ?? t;
  return key in PRIMITIVE_DEFINITIONS ? key : null;
}

/** Build the adapter bound to the app's public origin. */
export function makeIrlAdapter(origin: string): IrlAdapter {
  // Resilient JSON/text fetch — the canon reads are same-origin server-to-server
  // calls that intermittently blip on Lambda cold starts / Supabase latency. A
  // single transient failure must NOT surface to the agent as "could not reach
  // the canon" (the flaky-connector symptom, 2026-07-21). Shared with
  // publicKnowledge.ts via resilientFetch.ts (extracted 2026-09-03) — one
  // implementation, not a per-adapter fork.
  const get = (path: string) => resilientFetch(`${origin}${path}`);

  type PublicInvariant = Record<string, unknown> & { id?: string; seedId?: string | null };
  const invariantSnapshot = async (params: URLSearchParams) => {
    // The canonical public route caps its own snapshot at 500. Fetch that
    // bounded projection once, then paginate it without adding another store.
    params.set('limit', '500');
    const r = await get(`/api/public/irl/invariants?${params.toString()}`);
    if (!r.ok) return { ok: false as const, error: `invariant registry unavailable (${r.status})` };
    const rows = ((r.body as { invariants?: unknown })?.invariants ?? []) as PublicInvariant[];
    return { ok: true as const, rows };
  };
  const page = (rows: PublicInvariant[], offset?: number, limit?: number) => {
    const start = Math.max(0, Number.isFinite(offset) ? Math.floor(offset!) : 0);
    const size = Math.min(100, Math.max(1, Number.isFinite(limit) ? Math.floor(limit!) : 25));
    return {
      invariants: rows.slice(start, start + size),
      offset: start,
      limit: size,
      total: rows.length,
      hasMore: start + size < rows.length,
      nextOffset: start + size < rows.length ? start + size : null,
      snapshotCap: 500,
    };
  };
  const exactInvariant = async (id: string) => {
    const clean = id.trim();
    if (!clean) return { ok: false as const, error: 'an invariant id is required' };
    const params = new URLSearchParams();
    // Seed ids are the stable public citations used by experiments. The route's
    // `ids` filter matches database ids, so seed-id lookup uses exact matching
    // over the bounded canonical snapshot rather than a fuzzy text query.
    if (!clean.startsWith('inv.')) params.set('ids', clean);
    const snapshot = await invariantSnapshot(params);
    if (!snapshot.ok) return snapshot;
    const invariant = snapshot.rows.find((row) => row.id === clean || row.seedId === clean) ?? null;
    return invariant
      ? { ok: true as const, invariant }
      : { ok: false as const, error: 'invariant_not_found', id: clean };
  };

  return {
    async listInvariants(input = {}) {
      const params = new URLSearchParams();
      if (input.namespace) params.set('namespace', input.namespace);
      if (input.status) params.set('status', input.status);
      if (input.domain) params.set('domain', input.domain);
      const snapshot = await invariantSnapshot(params);
      if (!snapshot.ok) return snapshot;
      return {
        ok: true,
        ...page(snapshot.rows, input.offset, input.limit),
        source: 'canonical public IRL invariant registry',
        paginationBoundary: 'bounded published snapshot',
      };
    },
    async getInvariant(id: string) {
      const result = await exactInvariant(id);
      return result.ok
        ? { ...result, source: 'canonical public IRL invariant registry' }
        : result;
    },
    async searchInvariants(query, input = {}) {
      const clean = query.trim();
      if (!clean) return { ok: false, error: 'a search query is required' };
      const params = new URLSearchParams({ q: clean });
      if (input.namespace) params.set('namespace', input.namespace);
      if (input.status) params.set('status', input.status);
      const snapshot = await invariantSnapshot(params);
      if (!snapshot.ok) return snapshot;
      return {
        ok: true,
        query: clean,
        searchMode: 'keyword',
        ...page(snapshot.rows, input.offset, input.limit),
        source: 'canonical public IRL invariant registry',
      };
    },
    async listInvariantsForExperiment(experimentId) {
      const clean = experimentId.trim().toUpperCase();
      if (!clean) return { ok: false, error: 'an experiment id is required' };
      const overview = await get('/api/public/irl/research-overview');
      if (!overview.ok) return { ok: false, error: `research registry unavailable (${overview.status})` };
      const experiments = ((overview.body as { experiments?: unknown })?.experiments ?? []) as Array<Record<string, unknown>>;
      const entry = experiments.find((row) => {
        const experiment = row.experiment as Record<string, unknown> | undefined;
        return String(experiment?.id ?? '').toUpperCase() === clean;
      });
      const experiment = entry?.experiment as Record<string, unknown> | undefined;
      if (!experiment) return { ok: false, error: 'experiment_not_found', experimentId: clean };
      const ids = Array.isArray(experiment.governingInvariants)
        ? experiment.governingInvariants.filter((id): id is string => typeof id === 'string')
        : [];
      const resolved = await Promise.all(ids.map((id) => exactInvariant(id)));
      return {
        ok: true,
        experimentId: clean,
        governingInvariantIds: ids,
        invariants: resolved.filter((item) => item.ok).map((item) => item.invariant),
        unresolvedIds: resolved.filter((item) => !item.ok).map((item) => 'id' in item ? item.id : null).filter(Boolean),
        source: 'canonical research registry governingInvariants → canonical public invariant registry',
      };
    },
    async getInvariantLineage(id) {
      const exact = await exactInvariant(id);
      if (!exact.ok) return exact;
      const invariantId = String(exact.invariant.id ?? '');
      const field = await get(`/api/public/irl/invariant-field?id=${encodeURIComponent(invariantId)}`);
      return {
        ok: true,
        invariant: exact.invariant,
        supersedesId: exact.invariant.supersedesId ?? null,
        fieldNeighborhood: field.ok ? field.body : null,
        lineageScope: 'recorded supersession plus enables/constrains/contradicts neighbourhood; not a complete provenance graph',
        source: 'canonical public invariant registry and invariant-field projection',
      };
    },
    // The IRL research overview is the shared-artifact index (public).
    async listDocuments() {
      const r = await get('/api/public/irl/research-overview');
      if (!r.ok) return { ok: false, error: `research overview unavailable (${r.status})` };
      return { ok: true, overview: r.body, note: 'Use read_shared_document with a foundation/... path to read a specific artifact.' };
    },
    // Raw markdown for a repo-relative path within the IRL pack (public, T2-safe).
    async readDocument(path: string) {
      const clean = (path ?? '').trim();
      if (!clean || clean.includes('..')) return { ok: false, error: 'a valid IRL document path is required (e.g. foundation/PARTICIPATION_overview.md)' };
      const r = await get(`/api/public/irl/doc?path=${encodeURIComponent(clean)}`);
      if (!r.ok) return { ok: false, error: `document not found or unavailable (${r.status})`, path: clean };
      return { ok: true, path: clean, content: r.body };
    },
    // Define a primitive CONSTITUTIONAL-FIRST. Layer 1 = the verbatim ratified
    // defining invariants (the "what"); Layer 2 = the operational resolver
    // projection (the "how"), clearly labelled as a p0-shadow ranking so it is
    // never mistaken for the definition. The fix for the surfacing defect where
    // explain_primitive returned only the discovery-ranking vector.
    async definePrimitive(term: string) {
      const t = (term ?? '').trim();
      if (!t) return { ok: false, error: 'a term to define is required (e.g. "standing", "delegation", "Polity Passport").' };

      const canonByIds = async (ids: string[]) => {
        if (!ids.length) return [] as Array<{ id: string; statement: string; status: string; namespace: string }>;
        const r = await get(`/api/public/irl/invariants?ids=${encodeURIComponent(ids.join(','))}`);
        const rows = (r.ok && (r.body as { invariants?: unknown })?.invariants) || [];
        const byId = new Map<string, { id: string; statement: string; status: string; namespace: string }>();
        for (const row of rows as Array<Record<string, unknown>>) {
          if (typeof row.id === 'string') {
            byId.set(row.id, {
              id: row.id,
              statement: String(row.statement ?? ''),
              status: String(row.status ?? ''),
              namespace: String(row.namespace ?? ''),
            });
          }
        }
        // Preserve the curated (definition-first) order.
        return ids.map((id) => byId.get(id)).filter((x): x is NonNullable<typeof x> => Boolean(x));
      };

      // Layer 2 — the operational resolver projection (confidence-tagged, honest
      // about being a p0-shadow ranking, not the definition).
      const operationalLayer = async () => {
        const op = (await this.resolveCanon(t)) as { ok?: boolean; resolved?: Record<string, unknown> };
        const resolved = op?.resolved ?? {};
        return {
          note: 'How the runtime operationalizes the term — a resolver ranking projection, NOT the constitutional definition. Read Layer 1 for meaning.',
          phase: resolved.phase ?? null,
          confidence: resolved.confidence ?? null,
          citedIds: resolved.citedIds ?? [],
          caveat:
            'The resolver runs in a shadow phase; its scores calibrate confidence and ranking, they do not define the term. Any "standing" vector here is the discovery-ranking weight landscape (inv.reasoning.134-137), not constitutional Standing.',
        };
      };

      // Layer-1 by canon TEXT SEARCH — the resilient path (the one that answered
      // "Founder Office" while the ids path blipped). Used un-curated, and as the
      // fallback for a curated term whose ids read transiently fails.
      const qSearch = async (query: string) => {
        const searched = await get(`/api/public/irl/invariants?q=${encodeURIComponent(query)}&limit=40`);
        const rows = ((searched.ok && (searched.body as { invariants?: unknown })?.invariants) || []) as Array<Record<string, unknown>>;
        const rank = (s: string) => (s === 'canonical' ? 0 : s === 'validated' ? 1 : s === 'proposed' ? 2 : 3);
        const lower = query.toLowerCase();
        return rows
          .map((r) => ({
            id: String(r.id ?? ''),
            statement: String(r.statement ?? ''),
            status: String(r.status ?? ''),
            namespace: String(r.namespace ?? ''),
          }))
          .sort((a, b) => {
            const aLead = a.statement.toLowerCase().startsWith(lower) ? 0 : 1;
            const bLead = b.statement.toLowerCase().startsWith(lower) ? 0 : 1;
            return aLead - bLead || rank(a.status) - rank(b.status);
          })
          .slice(0, 6);
      };

      const key = definitionKey(t);
      if (key) {
        const def = PRIMITIVE_DEFINITIONS[key];
        // Best-effort Layer 1: curated ids first; if that read blips, fall back to
        // the resilient text search. The `distinctions` below are held IN THE
        // GATEWAY (not fetched), so the load-bearing constitutional guards
        // (e.g. Standing is personhood-bound and is NOT reputation) ALWAYS answer
        // even if every canon read is momentarily unavailable — never a hard fail.
        let invariants = await canonByIds(def.leadIds);
        let retrievedVia = 'curated defining invariants (by id)';
        if (!invariants.length) {
          invariants = await qSearch(t);
          retrievedVia = 'canon text search (ids read temporarily unavailable — retry for the full curated set)';
        }
        return {
          ok: true,
          term: t,
          source: 'live ratified invariant canon (public projection)',
          constitutionalDefinition: {
            layer: 1,
            meaning: invariants.length
              ? 'The constitutional meaning of the term, stated by the ratified invariants that govern it (definition-first, canonical statements lead).'
              : 'The canon read is momentarily unavailable; the constitutional distinctions below are the authoritative guards for this term (held in the gateway, not fetched). Retry for the full ratified statements.',
            invariants,
            retrievedVia,
          },
          distinctions: def.distinctions ?? [],
          operationalModel: { layer: 2, ...(await operationalLayer()) },
          note: 'Answered constitutional-first: Layer 1 is the ratified definition (the "what") plus the load-bearing distinctions; Layer 2 is the operational model (the "how"). These are the canon, not an inference.',
        };
      }

      // Un-curated term: resilient text search, highest-authority first.
      const sorted = await qSearch(t);
      if (!sorted.length) {
        return {
          ok: true,
          term: t,
          source: 'live ratified invariant canon (public projection)',
          constitutionalDefinition: null,
          operationalModel: { layer: 2, ...(await operationalLayer()) },
          note: `No ratified invariant matched "${t}" (or the canon read is momentarily unavailable). The operational resolver projection is provided; retry, or treat as a canon gap if it persists.`,
        };
      }
      return {
        ok: true,
        term: t,
        source: 'live ratified invariant canon (public projection)',
        constitutionalDefinition: {
          layer: 1,
          meaning: `Ratified invariants matching "${t}" (canon text search, highest-authority first). Not a hand-curated definition set — read the statements directly.`,
          invariants: sorted,
        },
        distinctions: [],
        operationalModel: { layer: 2, ...(await operationalLayer()) },
        note: 'Answered constitutional-first from a canon search: Layer 1 is the ratified statements; Layer 2 is the operational model.',
      };
    },
    // Resolve a constitutional term against the live invariant canon (public
    // resolve surface — the SAME resolver the platform uses, T2-safe projection).
    async resolveCanon(term: string) {
      const t = (term ?? '').trim();
      if (!t) return { ok: false, error: 'a term to define is required (e.g. "standing", "delegation", "Polity Passport").' };
      const r = await resilientFetch(`${origin}/api/public/irl/resolve`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ intent: `Define the constitutional meaning of "${t}" as a metaMe / Polity protocol primitive.` }),
      });
      const body = r.body as { ok?: boolean } | null;
      if (!r.ok || !body?.ok) return { ok: false, error: `canon unavailable for "${t}" (${r.status})`, term: t };
      return {
        ok: true,
        term: t,
        source: 'live ratified invariant canon (public projection)',
        resolved: body,
        note: 'These are ratified invariants that govern the term — the authoritative definition, not an inference.',
      };
    },
    // Published experiment results — the raw, hash-committed record so a reviewer
    // can verify hashes through the Threshold (review QA §3, Austin 2026-07-21).
    async readResults(experiment?: string) {
      const r = await get('/api/public/irl/experiments-results');
      if (!r.ok) return { ok: false, error: `published results unavailable (${r.status})` };
      const body = r.body as { results?: Array<Record<string, unknown>> } | null;
      let results = body?.results ?? [];
      const filt = (experiment ?? '').trim().toUpperCase();
      if (filt) results = results.filter((x) => String(x.experiment ?? '').toUpperCase() === filt);
      return {
        ok: true,
        count: results.length,
        results,
        note: 'Published, hash-committed, DVN-anchored results (T2-safe — no persona ids). To verify: recompute sha256 over the verbatim results JSON and compare to the anchored content hash.',
      };
    },
    async submitResult(input) {
      if (!input.agreementId) return { ok: false, error: 'no IRL submission agreement — enter the Researcher journey / IRL first (request_service_capabilities("irl")).' };
      try {
        const res = await fetch(`${origin}/api/public/irl/experiments/submit`, {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          cache: 'no-store',
          body: JSON.stringify({
            agreementId: input.agreementId,
            experiment: input.experiment,
            provider: input.provider,
            model: input.model,
            results: input.results,
            aggregates: input.aggregates ?? {},
          }),
        });
        const body = await res.json().catch(() => null);
        // The CFS-042 endpoint carries its own x409/TTL/budget gate — pass its
        // verdict straight through (ok:false with the constitutional reason).
        return body ?? { ok: false, error: `submit failed (${res.status})` };
      } catch {
        return { ok: false, error: 'could not reach the IRL submission endpoint' };
      }
    },
  };
}

/**
 * publicKnowledge.ts — the public knowledge & discovery layer for the
 * Threshold MCP Bridge, spanning Qriptopian, IRL OS, AgentiQ OS, and Polity
 * Core (operator directive, 2026-09-03: "Complete the public knowledge and
 * discovery layer for the Threshold MCP Bridge").
 *
 * DESIGN — smallest coherent cross-cartridge interface, not four parallel
 * tool families (per the directive's §5). One adapter, one document shape,
 * one search function, branching internally per cartridge on top of
 * ALREADY-CANONICAL read paths:
 *
 *   - qriptopian  → the live app/api/codex/qripto/{papers,essays} routes
 *     (same server-to-server fetch pattern irlAdapter.ts already uses for
 *     IRL — never a second Supabase query path for the same content).
 *   - irl-os      → delegates straight to the injected IrlAdapter
 *     (ctx.irl) — the SAME public, already-audited /api/public/irl/* reads
 *     the existing list_shared_documents/read_shared_document tools use.
 *     This module adds no new IRL read path.
 *   - agentiq-os  → the SAME corpusReadPackFile() seam
 *     app/api/codex/packs/[packId]/file/route.ts uses, restricted to an
 *     EXPLICIT allowlist (never a directory scan — the pack's own
 *     "Updates" tab is not adminOnly but resolves to 474 internal
 *     engineering session files that must never leak through discovery).
 *   - polity-core → the same corpusReadPackFile() seam, restricted to an
 *     explicit allowlist that excludes the one adminOnly commentary tab
 *     (the Constitutional Internet working manuscript).
 *
 * ACCESS CONTROL — default-deny, allowlist-only. No cartridge branch below
 * ever lists a directory or accepts a caller-supplied path; every readable
 * document id is a member of a hardcoded, audited constant. This is
 * deliberate: per-document publication-status fields do not exist yet for
 * three of these four cartridges (confirmed by direct audit, 2026-09-03),
 * so "default-allow, gated by some field" is not an option — an allowlist
 * is the only sound posture available today. Widening a cartridge's
 * allowlist requires the SAME operator classification review as the
 * original one (never inferred from a tab's `enabled`/`adminOnly` flag
 * alone, and never from a repository/URL/domain/"active status" signal —
 * see this module's own audit trail in
 * codexes/packs/agentiq/updates/2026-09-03_threshold-public-knowledge-bridge.md).
 *
 * SEARCH — keyword only (substring/token match over title + excerpt +
 * resolved text), explicitly reported as such (`searchMode: 'keyword'`) in
 * every response. Semantic search over this content would route through
 * services/content/embeddingService.ts, which has a confirmed, live hazard
 * (processUnembeddedChunks() drains ALL domains with no scoping, including
 * the private `homecoming` KB) — this module never calls it. Wiring real
 * semantic search is out of scope for this pass; see the audit trail doc.
 *
 * PROVENANCE — read_public_document always returns the FULL resolved text's
 * sha256 alongside any requested page, so an agent reconstructing the full
 * text across pages can verify it against the same hash regardless of how
 * it was paginated.
 */

